def protocol_handlers(cls, protocol_version=None):
    if not protocol_version or type(protocol_version) is not tuple:
        raise TypeError("protocol_version must be a tuple")

    supported_versions = (3, 5, 4, 4.1, 3.5)
    relevant_versions = supported_versions if protocol_version is None else (protocol_version,)
    handlers = {}

    for version in relevant_versions:
        if version in supported_versions:
            handlers[version] = cls._Bolt4Handler if version >= (4,) else cls._Bolt3Handler

    return handlers

