def normalize_args(sequence, output=None):
    """
    Normalize declaration arguments

    :param sequence: The sequence of interfaces or implements specs
    :param output: The output type of the normalized interface
    :return: The normalized interface or None
    """

    if len(sequence) == 0:
        raise ValueError("Cannot normalize an empty sequence")

    # Handle the case where the sequence contains a single interface
    if len(sequence) == 1:
        elem = sequence[0]
        if isinstance(elem, Interface):
            return elem
        elif isinstance(elem, tuple):
            return elem
        else:
            raise ValueError(f"Invalid input type: {type(elem)}")

    # Handle the case where the sequence contains a multiple interfaces or tuples
    output_type = type(output) if output else None
    normalized_interfaces = []
    for elem in sequence:
        if isinstance(elem, Interface):
            normalized_interfaces.append(elem)
        elif isinstance(elem, tuple):
            normalized_interfaces.extend(elem)
        else:
            raise ValueError(f"Invalid input type: {type(elem)}")

    # Check if the output type has been specified and the normalized interfaces match the output type
    if output_type and len(normalized_interfaces) > 1:
        for i, interface in enumerate(normalized_interfaces):
            if not issubclass(interface, output_type):
                raise ValueError(f"Invalid output type for element {i}: {interface}")

    # Return the normalized interfaces
    return tuple(normalized_interfaces) if output_type else normalized_interfaces

