def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord[0] < 0 or coord[1] < 0:
        raise ValueError("Coordinates outside the histogram edges are invalid.")
    if weight < 0:
        raise ValueError("Weights cannot be negative.")
    if coord[0] >= self.size[0] or coord[1] >= self.size[1] or coord[0] < 0 or coord[1] < 0:
        return
    self.counts[coord[0]][coord[1]] += weight
    if self.counts[coord[0]][coord[1]] < 0:
        raise RuntimeError("Overflow occurred when adding weight to the histogram.")

