def format(sql, params):
    if not isinstance(params, (dict, list)):
        raise ValueError("params must be a dict or list")

    if isinstance(params, list):
        if len(params) != len(set(params)):
            raise ValueError("params must not contain duplicate values")

        params = dict((i, v) for i, v in enumerate(params))

    if SQLParams.in_style == "named":
        if not isinstance(params, dict):
            raise ValueError("params must be a dict")

        sql = sql.replace("%s", ":{}")
        params = dict((k, v) for k, v in params.items())
    else:
        if not isinstance(params, list):
            raise ValueError("params must be a list")

        sql = sql.replace("%s", "?")

    return (sql, params)

def formatmany(sql, many_params):
    # Check if the input is valid
    if not isinstance(sql, str):
        raise ValueError("SQL query must be a string")
    if not isinstance(many_params, Iterable):
        raise ValueError("Many parameters must be an iterable")

    # Initialize the formatted SQL query and a list to store the converted parameters
    formatted_sql = ""
    params = []

    # Iterate over each set of in-style parameters
    for i, params_list in enumerate(many_params):
        # Check if the current set of parameters is valid
        if not isinstance(params_list, (Mapping, Sequence)):
            raise ValueError(f"Parameters for input {i} must be a mapping or a sequence")

        # Check if the mapping is using ordinal parameters
        if isinstance(params_list, Mapping):
            if not all([isinstance(k, (str, int)) and isinstance(v, Any) for k, v in params_list.items()]):
                raise ValueError("Invalid parameter mapping. Each item must be a (str, int) pair")

        # Check if the sequence is using ordinal parameters
        elif isinstance(params_list, Sequence) and not all([isinstance(p, Any) for p in params_list]):
            raise ValueError("Invalid parameter sequence. Each item must be an object")

        # Format the SQL query using out-style parameters
        formatted_sql = sql.format(*params_list)
        if i < len(many_params) - 1:
            formatted_sql += ","

        # Add the converted parameters to the list
        if isinstance(params_list, Sequence):
            params.append(list(params_list))
        else:
            params.append({k: v for k, v in params_list.items()})

    return formatted_sql, params

