def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not 0 <= number < len(alphabet):
        raise ValueError(f"Invalid number {number} out of range")
    if padding is not None and padding < 0:
        raise ValueError(f"Invalid padding {padding}, must be non-negative")

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        digits.extend([alphabet[0] for _ in range(padding - len(digits))])

    return "".join(digits[::-1])

