class RequestHandler:

    @classmethod
    def validate_from_content(cls, spec_content=None):
        try:
            data = yaml.safe_load(spec_content)
            if not data:
                raise IRValidatorException("Spec file is empty")
            for field in ["id", "data_source"]:
                if not field in data:
                    raise IRValidatorException(f"Mandatory field '{field}' is missing in spec file")
            return data
        except yaml.scanner.ScannerError as e:
            raise IRValidatorException(f"Invalid spec file: {e}")

@staticmethod
def validate_from_file(yaml_file):
    with open(yaml_file, 'r') as f:
        try:
            yaml_data = yaml.safe_load(f)
        except yaml.YAMLError as err:
            raise IRValidatorException(f'Failed to load YAML file: {str(err)}')

    # Verify that all mandatory keys are present in the YAML data
    required_keys = ['foo', 'bar', 'baz']
    for key in required_keys:
        if key not in yaml_data:
            raise IRValidatorException(f'Missing mandatory key: {key}')

    # Return the validated data
    return yaml_data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dict of resolved argument values.
    """
    resolved_args = {}
    for arg in self.spec.args:
        if arg.default is not None:
            # Use the specified default value if provided
            resolved_args[arg.name] = arg.default
        else:
            # Try to resolve the argument value using the "get" method
            try:
                resolved_args[arg.name] = self.get(arg.name)
            except AttributeError:
                # If the "get" method is not implemented, use the "default" value if provided
                if arg.default is not None:
                    resolved_args[arg.name] = arg.default
                else:
                    raise ValueError(f"Argument {arg.name} has no default value and cannot be resolved.")
    return resolved_args

def get_deprecated_args(self):
    deprecated_args = {}

    # Get the current argument values from the parsed command line
    current_args = self.parsed_args.get_argspec()

    # Get the list of deprecated arguments
    deprecated_args_list = self.get_deprecated_arg_list()

    # Iterate over the list of deprecated arguments
    for deprecated_arg in deprecated_args_list:
        # Check if the deprecated argument is in the current argument values
        if deprecated_arg in current_args:
            # If it is, add it to the dictionary with a value of True
            deprecated_args[deprecated_arg] = True

    return deprecated_args

def get_silent_args(self, args):
        """
